-- 누가 만드는지 확인한다

@Test
void 누가_만드나() {
    em.clear();
    MemberDto a = em.createQuery(
            "select new study.querydsl.dto.MemberDto(m.username, m.age)" +
            " from Member m where m.username = 'm1'", MemberDto.class)
        .getSingleResult();

    em.clear();
    MemberDto b = queryFactory
            .select(Projections.constructor(MemberDto.class,
                    member.username, member.age))
            .from(member)
            .where(member.username.eq("m1"))
            .fetchOne();

    System.out.println("JPQL:     " + a.getUsername() + " " + a.getAge());
    System.out.println("Querydsl: " + b.getUsername() + " " + b.getAge());
}

